{
  "packet_id": "H6-T01-1",
  "claim_id": "C012",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C012.component",
    "value": "Collection must not be treated as actual start unless their relationship has been verified.",
    "scope": "Operational event definitions; the mapping does not assert that verification has occurred or specify its test.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P006 explicitly supplies the event distinction and verification condition."
    }
  },
  "signal_basis": {
    "component_id": "C012.signal_basis",
    "value": "Record turnaround events comparably using distinct definitions of readiness, collection and actual start, and seek recurring readiness delays or repeated late collection after documented readiness.",
    "scope": "Prospective turnaround observations; the described signal is assumed to occur, but does not itself establish equivalence between collection and actual start.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the event definitions, comparable recording operation, candidate temporal signals and their prospective status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C012.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is a warranted measurement restriction, not an inference awaiting establishment of an empirical relation."
    }
  },
  "rationale": "Collection and actual start denote distinct events. Repeated collection or readiness patterns do not establish that collection measures actual start. Requiring verification before that substitution is therefore licensed within the claim's operational scope.",
  "uncertainty": "The mapping leaves the verification test and its outcome unspecified; neither is required to support this restriction.",
  "anomalies": []
}
